/* Each line is a clipping box; its inner text slides up out of it while the line scrolls into
   view (over a fixed 280px of scroll, each line 40px later than the one above). The fade
   variant rises 28px and fades in instead, without clipping. */
.castelion-lines-line {
  view-timeline-name: --castelion-line;
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .castelion-lines-inner {
      animation: castelion-lines-rise linear both;
      animation-timeline: --castelion-line;
      animation-range: entry calc(var(--castelion-line-i, 0) * 40px) entry calc(280px + var(--castelion-line-i, 0) * 40px);
    }
    .castelion-lines[data-variant="fade"] .castelion-lines-inner {
      animation-name: castelion-lines-fade;
    }
  }
}

@keyframes castelion-lines-rise {
  from { transform: translateY(110%); }
  to { transform: none; }
}

@keyframes castelion-lines-fade {
  from { opacity: 0; transform: translateY(28px); }
  to { opacity: 1; transform: none; }
}

import { Fragment, type CSSProperties, type ElementType } from "react";
import { cn } from "@foundry/foundry-utils";
import "./castelion-lines.css";

export interface CastelionLinesProps {
  /** the text, one entry per desktop line (phones let the entries flow and wrap) */
  lines: string[];
  /** the element to render, e.g. "h2" or "p" */
  as?: ElementType;
  /** mask: each line slides up out of a clip (titles) · fade: each line rises 28px and fades in (copy) */
  variant?: "mask" | "fade";
  /** where the stagger starts counting, to continue it from text above */
  startIndex?: number;
  className?: string;
}

/** Text revealed line by line as it scrolls into view. */
export function CastelionLines({ lines, as: Tag = "p", variant = "mask", startIndex = 0, className }: CastelionLinesProps) {
  return (
    <Tag className={cn("castelion-lines", className)} data-variant={variant}>
      {lines.map((line, i) => (
        <Fragment key={i}>
          {i > 0 && <br className="max-lg:hidden" />}
          {i > 0 && " "}
          <span
            className={cn(
              "castelion-lines-line inline-block align-top",
              variant === "mask" && "-mb-[0.14em] overflow-clip pb-[0.14em]",
              variant === "fade" && "max-lg:inline",
            )}
            style={{ "--castelion-line-i": startIndex + i } as CSSProperties}
          >
            <span className={cn("castelion-lines-inner block", variant === "fade" && "max-lg:inline")}>{line}</span>
          </span>
        </Fragment>
      ))}
    </Tag>
  );
}
